import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'

// The Ruby server (../server.rb) serves everything from ../public as its
// DocumentRoot, so the build output goes straight there — server.rb never
// needs to change. Don't hand-edit anything under ../public; it's
// regenerated by `npm run build` every time.
export default defineConfig({
  plugins: [react()],
  base: './',
  build: {
    outDir: '../public',
    emptyOutDir: true,
  },
  server: {
    // `npm run dev` for hot-reload while iterating on the UI — proxies API
    // calls to the real Ruby backend, which must be running separately
    // (`../start.sh`). This dev server is never what serves the app day to
    // day; `npm run build` + the Ruby server (DocumentRoot = ../public) is.
    proxy: {
      '/api': 'http://localhost:4568',
    },
  },
  test: {
    environment: 'jsdom',
    globals: true,
    setupFiles: './src/test/setup.js',
  },
})
